}

.seat-limit-info {
  text-align: center;
}

.screen-indicator {
  margin: 0 auto 16px;
  width: 60%;
  text-align: center;
  background: #444;
  color: #fff;
  padding: 8px;
  letter-spacing: 4px;
  border-radius: 4px 4px 50% 50% / 4px 4px 16px 16px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 24px;
}

.seat-row {
  display: grid;
  grid-template-columns: 32px repeat(4, 28px) 56px repeat(16, 28px) 56px repeat(4, 28px) 32px;
  align-items: center;
  gap: 2px;
}

.row-label {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
}

.cell {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  width: 100%;
  font-size: 10px;
  border: none;
  border-radius: 2px;
  padding: 0;
  color: #fff;
  cursor: pointer;
}

.cell.empty,
.cell.aisle {
  background: transparent;
  cursor: default;
}

.cell.empty {
  grid-column: span 4;
}

.cell.couch {
  grid-column: span 2;
  font-size: 9px;
}

.legend {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.swatch {
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 2px;
}

.selected-seats {
  margin-bottom: 24px;
}

.actions {
  display: flex;
  gap: 12px;
