@if (loaded()) {
  <h1 data-testid="summary-title">Your tickets</h1>

  <div data-testid="summary-list" class="summary-list">
    @for (item of items(); track item.ids.join('-')) {
      <div data-testid="summary-item" class="summary-item">
        <span data-testid="summary-item-title">{{ movie()?.title }}</span>
        <span data-testid="summary-item-datetime">{{ dateTime() }}</span>
        <span data-testid="summary-item-row">{{ item.row }}</span>
