        <button mat-stroked-button type="button" data-testid="summary-item-remove-button" (click)="remove(item)">Remove</button>
      </div>
    }
  </div>

  <div data-testid="summary-total" class="summary-total">Total: {{ formatPrice(total()) }}</div>

  <div class="actions">
    <button mat-stroked-button type="button" data-testid="back-button" (click)="back()">Back</button>
    <button mat-raised-button type="button" data-testid="confirm-button" (click)="confirm()">Confirm</button>
  </div>
}

