@if (booking()) {
  <h1 data-testid="checkout-title">Your details</h1>

  <div [formGroup]="form" class="form">
    <mat-form-field>
      <mat-label data-testid="first-name-label">First name *</mat-label>
      <input matInput data-testid="first-name-input" formControlName="firstName" />
    </mat-form-field>
    @if (fieldError('firstName', 'First name is required', 'minlength', 'First name must be at least 2 characters'); as message) {
      <div data-testid="first-name-error">{{ message }}</div>
    }

    <mat-form-field>
      <mat-label data-testid="last-name-label">Last name *</mat-label>
      <input matInput data-testid="last-name-input" formControlName="lastName" />
    </mat-form-field>
    @if (fieldError('lastName', 'Last name is required', 'minlength', 'Last name must be at least 2 characters'); as message) {
      <div data-testid="last-name-error">{{ message }}</div>
    }

    <mat-form-field>
      <mat-label data-testid="email-label">Email *</mat-label>
      <input matInput data-testid="email-input" formControlName="email" />
    </mat-form-field>
    @if (fieldError('email', 'Email is required', 'emailFormat', 'Enter a valid email address'); as message) {
      <div data-testid="email-error">{{ message }}</div>
    }

    <mat-form-field>
      <mat-label data-testid="confirm-email-label">Confirm email *</mat-label>
      <input matInput data-testid="confirm-email-input" formControlName="confirmEmail" />
    </mat-form-field>
    @if (fieldError('confirmEmail', 'Confirm email is required', 'mismatch', 'Email addresses do not match'); as message) {
      <div data-testid="confirm-email-error">{{ message }}</div>
    }

    <mat-form-field>
      <mat-label data-testid="phone-label">Phone number</mat-label>
      <input matInput data-testid="phone-input" formControlName="phone" />
    </mat-form-field>
    @if (fieldError('phone', '', 'pattern', 'Phone number must be exactly 9 digits'); as message) {
      <div data-testid="phone-error">{{ message }}</div>
    }

    <mat-checkbox data-testid="terms-checkbox" formControlName="termsAccepted" (change)="touchTerms()">
      <span data-testid="terms-label">I accept the terms and conditions *</span>
    </mat-checkbox>
    @if (
      fieldError('termsAccepted', 'You must accept the terms and conditions', 'required', 'You must accept the terms and conditions');
      as message
    ) {
      <div data-testid="terms-error">{{ message }}</div>
    }
  </div>

  <div class="actions">
    <button mat-stroked-button type="button" data-testid="checkout-back-button" (click)="back()">Back</button>
    <button mat-raised-button type="button" data-testid="pay-button" [disabled]="submitting()" (click)="pay()">
      {{ submitting() ? 'Processing…' : 'Pay ' + formatPrice(total()) }}
    </button>
  </div>
}

