1	import { Component, computed, effect, inject, signal } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { MatButtonModule } from '@angular/material/button';
4	import { ActivatedRoute, Router } from '@angular/router';
5	import { map } from 'rxjs';
6	import { BookingService } from '../../core/services/booking.service';
7	import { MoviesService } from '../../core/services/movies.service';
8	import { ToastService } from '../../core/services/toast.service';
9	import { Screening } from '../../core/models/screening.model';
10	import { AuditoriumRow, SeatState, buildAuditorium, cellIds, stateOf } from '../../shared/auditorium';
11	import { formatShowDate } from '../../shared/date-utils';
12	import { SeatGroup, groupSeats } from '../../shared/seat-grouping';
13	import { LEGEND_ITEMS, SEAT_COLORS } from '../../shared/seat-colors';
14	
15	@Component({
16	  selector: 'app-seat-map',
17	  imports: [MatButtonModule],
18	  templateUrl: './seat-map.component.html',
19	  styleUrl: './seat-map.component.scss',
20	})
21	export class SeatMapComponent {
22	  private readonly route = inject(ActivatedRoute);
23	  private readonly router = inject(Router);
24	  private readonly moviesService = inject(MoviesService);
25	  private readonly bookingService = inject(BookingService);
26	  private readonly toastService = inject(ToastService);
27	
28	  private readonly screeningId = toSignal(
29	    this.route.paramMap.pipe(map((params) => Number(params.get('id')))),
30	    { initialValue: NaN },
31	  );
32	
33	  readonly rows: AuditoriumRow[] = buildAuditorium();
34	  readonly legendItems = LEGEND_ITEMS;
35	
36	  readonly screening = signal<Screening | null>(null);
37	  readonly loaded = signal(false);
38	
39	  readonly booking = this.bookingService.booking;
40	
41	  readonly occupiedSet = computed(() => new Set(this.screening()?.occupiedSeats ?? []));
42	  readonly selectedSet = computed(() => new Set(this.booking()?.seats ?? []));
43	  readonly selectedCount = computed(() => this.booking()?.seats.length ?? 0);
44	  readonly selectedGroups = computed<SeatGroup[]>(() => groupSeats(this.booking()?.seats ?? []));
45	  readonly selectedRows = computed(() => [...new Set(this.selectedGroups().map((group) => group.row))].sort((a, b) => a - b));
46	
47	  readonly subtitle = computed(() => {
48	    const screening = this.screening();
49	    return screening ? `Show Date: ${formatShowDate(screening.date, screening.time)}` : '';
50	  });
51	
52	  constructor() {
53	    effect(() => {
54	      const id = this.screeningId();
55	      if (Number.isNaN(id)) {
56	        this.router.navigateByUrl('/');
57	        return;
58	      }
59	      this.load(id);
60	    });
61	  }
62	
63	  private load(id: number): void {
64	    this.moviesService.getScreening(id).subscribe({
65	      next: (screening) => {
66	        this.bookingService.ensureBookingForScreening(id);
67	        this.screening.set(screening);
68	        this.loaded.set(true);
69	      },
70	      error: () => this.router.navigateByUrl('/'),
71	    });
72	  }
73	
74	  seatColor(state: SeatState): string {
75	    return SEAT_COLORS[state];
76	  }
77	
78	  cellState(ids: string[], accessible: boolean): SeatState {
79	    return stateOf(ids, accessible, this.occupiedSet(), this.selectedSet());
80	  }
81	
82	  idsFor(cell: Parameters<typeof cellIds>[0]): string[] {
83	    return cellIds(cell);
84	  }
85	
86	  onSeatClick(ids: string[], state: SeatState): void {
87	    if (state === 'unavailable') {
88	      return;
89	    }
90	    const result = this.bookingService.toggleSeats(ids);
91	    if (result === 'limit') {
92	      this.toastService.show('Maximum 10 seats per booking');
93	    }
94	  }
95	
96	  rowGroupLine(row: number): string {
97	    const parts = this.selectedGroups()
98	      .filter((group) => group.row === row)
99	      .map((group) => (group.kind === 'couch' ? `${group.columnStart}-${group.columnEnd}` : `${group.column}`));
100	    return `Row ${row}: ${parts.join(', ')}`;
101	  }
102	
103	  cancel(): void {
104	    this.bookingService.clearBooking();
105	    this.router.navigateByUrl('/');
106	  }
107	
108	  continue(): void {
109	    if (this.selectedCount() === 0) {
110	      return;
111	    }
112	    this.router.navigate(['/screenings', this.screeningId(), 'summary']);
113	  }
114	}
