1	import { priceForRow } from './seat-pricing';
2	
3	export interface SeatGroup {
4	  row: number;
5	  kind: 'seat' | 'couch';
6	  column: number | null;
7	  columnStart: number | null;
8	  columnEnd: number | null;
9	  price: number;
10	  ids: string[];
11	}
12	
13	export function parseSeatId(id: string): { row: number; column: number } {
14	  const match = /^R(\d+)C(\d+)$/.exec(id);
15	  if (!match) {
16	    throw new Error(`Invalid seat id: ${id}`);
17	  }
18	  return { row: Number(match[1]), column: Number(match[2]) };
19	}
20	
21	export function groupSeats(ids: string[]): SeatGroup[] {
22	  const parsed = ids.map((id) => ({ id, ...parseSeatId(id) }));
23	  const byRow = new Map<number, { id: string; row: number; column: number }[]>();
24	  for (const seat of parsed) {
25	    const list = byRow.get(seat.row) ?? [];
26	    list.push(seat);
27	    byRow.set(seat.row, list);
28	  }
29	
30	  const rows = [...byRow.keys()].sort((a, b) => a - b);
31	  const groups: SeatGroup[] = [];
32	  for (const row of rows) {
33	    const seats = [...(byRow.get(row) ?? [])].sort((a, b) => a.column - b.column);
34	    if (row === 15) {
35	      for (let i = 0; i < seats.length; i += 2) {
36	        const first = seats[i];
37	        const second = seats[i + 1];
38	        groups.push({
39	          row,
40	          kind: 'couch',
41	          column: null,
42	          columnStart: first.column,
43	          columnEnd: second.column,
44	          price: priceForRow(row),
45	          ids: [first.id, second.id],
46	        });
47	      }
48	    } else {
49	      for (const seat of seats) {
50	        groups.push({
51	          row,
52	          kind: 'seat',
53	          column: seat.column,
54	          columnStart: null,
55	          columnEnd: null,
56	          price: priceForRow(row),
57	          ids: [seat.id],
58	        });
59	      }
60	    }
61	  }
62	  return groups;
63	}
64	
65	export function sortSeatsForSummary(ids: string[]): string[] {
66	  return [...ids].sort((a, b) => {
67	    const pa = parseSeatId(a);
68	    const pb = parseSeatId(b);
69	    return pa.row - pb.row || pa.column - pb.column;
70	  });
71	}
72	
73	export function totalPrice(ids: string[]): number {
74	  return groupSeats(ids).reduce((sum, group) => sum + group.price, 0);
75	}
